mod models;
mod execution_contracts { #[derive(Debug,Clone,serde::Serialize,serde::Deserialize)] pub enum ExecutionState{Succeeded,Failed,Unknown} }
#[path="sink.rs"] mod storage;
mod worker;
use models::SqlLogEntry;
use std::{fs,io::Write,path::{Path,PathBuf},time::Instant};
fn entry(i:usize)->SqlLogEntry{SqlLogEntry{ts:"2099-01-01 00:00:00".into(),connection_id:"perf".into(),connection_name:"isolated".into(),kind:"sqlite".into(),database:"private".into(),namespace:"main".into(),sql:format!("INSERT INTO items VALUES({i}, '中文测试')"),parameters:vec![],ok:true,elapsed_ms:0,rows:1,message:String::new(),origin:"tool".into(),operation_id:None,execution_state:Some(execution_contracts::ExecutionState::Succeeded)}}
// Pre-optimization IO implementation: a metadata probe, parent check, and open/write per entry.
fn baseline(path:&Path,e:&SqlLogEntry){if let Some(p)=path.parent(){let _=fs::create_dir_all(p);}if fs::metadata(path).map(|m|m.len()).unwrap_or(0)>8*1024*1024{storage::compact_for_benchmark(path);}if let Ok(mut f)=fs::OpenOptions::new().create(true).append(true).open(path){if let Ok(line)=serde_json::to_string(e){let _=writeln!(f,"{}",line);}}}
fn queued(events:Vec<(PathBuf,SqlLogEntry)>,optimized:bool){let(s,r)=std::sync::mpsc::channel();for(p,e)in events{s.send(worker::WriteEvent::Entry(p,e)).unwrap();}drop(s);if optimized{worker::run(r)}else{for ev in r{if let worker::WriteEvent::Entry(p,e)=ev{baseline(&p,&e);}}}}
#[tokio::main]
async fn main(){let root=std::env::temp_dir().join(format!("navkit-history-perf-{}",uuid::Uuid::new_v4()));fs::create_dir_all(&root).unwrap();let rows=20000;let mut rounds=vec![];
for round in 0..5{let mut timings=vec![];for optimized in if round%2==0{[false,true]}else{[true,false]}{let p=root.join(format!("io-{round}-{optimized}.jsonl"));let events=(0..rows).map(|i|(p.clone(),entry(i))).collect();let start=Instant::now();queued(events,optimized);let ms=start.elapsed().as_secs_f64()*1000.;timings.push(serde_json::json!({"optimized":optimized,"ms":ms}));}assert_eq!(fs::read(root.join(format!("io-{round}-false.jsonl"))).unwrap(),fs::read(root.join(format!("io-{round}-true.jsonl"))).unwrap());rounds.push(timings);}
let mut db_rounds=vec![];for round in 0..3{let mut timings=vec![];for optimized in if round%2==0{[false,true]}else{[true,false]}{let file=root.join(format!("db-{round}-{optimized}.sqlite"));let opts=sqlx::sqlite::SqliteConnectOptions::new().filename(&file).create_if_missing(true);let pool=sqlx::sqlite::SqlitePoolOptions::new().max_connections(1).connect_with(opts).await.unwrap();sqlx::query("CREATE TABLE items(id INTEGER PRIMARY KEY,note TEXT)").execute(&pool).await.unwrap();let p=root.join(format!("db-{round}-{optimized}.jsonl"));let(s,r)=std::sync::mpsc::channel();let writer=std::thread::spawn(move||if optimized{worker::run(r)}else{for ev in r{if let worker::WriteEvent::Entry(p,e)=ev{baseline(&p,&e);}}});let start=Instant::now();let mut tx=pool.begin().await.unwrap();for i in 0..rows{let log=entry(i);sqlx::raw_sql(&log.sql).execute(&mut *tx).await.unwrap();s.send(worker::WriteEvent::Entry(p.clone(),log)).unwrap();}tx.commit().await.unwrap();drop(s);writer.join().unwrap();let ms=start.elapsed().as_secs_f64()*1000.;let n:i64=sqlx::query_scalar("SELECT COUNT(*) FROM items").fetch_one(&pool).await.unwrap();assert_eq!(n,rows as i64);pool.close().await;timings.push(serde_json::json!({"optimized":optimized,"ms":ms,"rows":n}));}assert_eq!(fs::read(root.join(format!("db-{round}-false.jsonl"))).unwrap(),fs::read(root.join(format!("db-{round}-true.jsonl"))).unwrap());db_rounds.push(timings);}
let result=serde_json::json!({"benchmark":"product-history-io-and-real-sqlite-reference-workload","rows":rows,"io_rounds":rounds,"sqlite_rounds":db_rounds,"correctness":"byte-identical retained logs and exact row counts","cleanup":true,"navicat":"not measured"});fs::remove_dir_all(&root).unwrap();println!("{}",result);}
